const sensors = ['temperatura_c', 'humedad_pct', 'fosfina_mq135', 'co_mq7'];
const tempRange = { min: 18, max: 25 };
const humRange = { min: 30, max: 60 };

function toDate(raw) {
    const dt = new Date(raw);
    return Number.isFinite(dt.getTime()) ? dt : null;
}

function toSqlDate(dt) {
    return dt ? dt.toISOString().slice(0, 19).replace('T', ' ') : null;
}

function round(value, digits = 2) {
    return Number.isFinite(value) ? Number(value.toFixed(digits)) : null;
}

function mean(arr) {
    if (!arr.length) return null;
    return arr.reduce((sum, v) => sum + v, 0) / arr.length;
}

function variance(arr, avg) {
    if (!arr.length) return null;
    const m = Number.isFinite(avg) ? avg : mean(arr);
    if (!Number.isFinite(m)) return null;
    return arr.reduce((sum, v) => sum + Math.pow(v - m, 2), 0) / arr.length;
}

function stddev(arr, avg) {
    const v = variance(arr, avg);
    return Number.isFinite(v) ? Math.sqrt(v) : null;
}

function sorted(arr) {
    return arr.slice().sort((a, b) => a - b);
}

function quantile(sortedArr, q) {
    if (!sortedArr.length) return null;
    const pos = (sortedArr.length - 1) * q;
    const base = Math.floor(pos);
    const rest = pos - base;
    if (sortedArr[base + 1] !== undefined) {
        return sortedArr[base] + rest * (sortedArr[base + 1] - sortedArr[base]);
    }
    return sortedArr[base];
}

function median(arr) {
    return quantile(sorted(arr), 0.5);
}

function mode(arr) {
    if (!arr.length) return null;
    const counts = {};
    let best = null;
    let bestCount = 0;
    for (const v of arr) {
        const key = Number(v).toFixed(2);
        counts[key] = (counts[key] || 0) + 1;
        if (counts[key] > bestCount) {
            bestCount = counts[key];
            best = Number(key);
        }
    }
    return best;
}

function iqrBounds(arr) {
    if (arr.length < 4) return { lower: null, upper: null, q1: null, q3: null };
    const s = sorted(arr);
    const q1 = quantile(s, 0.25);
    const q3 = quantile(s, 0.75);
    const iqr = q3 - q1;
    return { lower: q1 - 1.5 * iqr, upper: q3 + 1.5 * iqr, q1, q3 };
}

function percentileBounds(arr, lowQ, highQ) {
    if (arr.length < 4) return { low: null, high: null };
    const s = sorted(arr);
    return { low: quantile(s, lowQ), high: quantile(s, highQ) };
}

function addCount(map, key) {
    const k = String(key);
    map[k] = (map[k] || 0) + 1;
}

function peakKey(map) {
    let best = null;
    let bestCount = -1;
    for (const [k, v] of Object.entries(map)) {
        if (v > bestCount) {
            bestCount = v;
            best = k;
        }
    }
    return best;
}

function pearson(pairs) {
    if (pairs.length < 3) return null;
    let sx = 0;
    let sy = 0;
    for (const [x, y] of pairs) {
        sx += x;
        sy += y;
    }
    const mx = sx / pairs.length;
    const my = sy / pairs.length;
    let num = 0;
    let dx = 0;
    let dy = 0;
    for (const [x, y] of pairs) {
        const vx = x - mx;
        const vy = y - my;
        num += vx * vy;
        dx += vx * vx;
        dy += vy * vy;
    }
    if (dx === 0 || dy === 0) return null;
    return num / Math.sqrt(dx * dy);
}

const rooms = {};

function ensureRoom(id) {
    if (!rooms[id]) {
        rooms[id] = {
            id_habitacion: id,
            total: 0,
            minTs: null,
            maxTs: null,
            values: {},
            series: {},
            pairs: { temp_hum: [], fosfina_co: [] }
        };
        for (const s of sensors) {
            rooms[id].values[s] = [];
            rooms[id].series[s] = [];
        }
    }
    return rooms[id];
}

for (const r of rows) {
    const id = String(r.id_habitacion || '').trim();
    if (!id) continue;
    const ts = toDate(r.timestamp_origen);
    if (!ts) continue;
    const room = ensureRoom(id);
    room.total += 1;
    if (!room.minTs || ts < room.minTs) room.minTs = ts;
    if (!room.maxTs || ts > room.maxTs) room.maxTs = ts;

    const temp = Number(r.temperatura_c);
    const hum = Number(r.humedad_pct);
    const fos = Number(r.fosfina_mq135);
    const co = Number(r.co_mq7);

    if (Number.isFinite(temp)) {
        room.values.temperatura_c.push(temp);
        room.series.temperatura_c.push({ ts, value: temp });
    }
    if (Number.isFinite(hum)) {
        room.values.humedad_pct.push(hum);
        room.series.humedad_pct.push({ ts, value: hum });
    }
    if (Number.isFinite(fos)) {
        room.values.fosfina_mq135.push(fos);
        room.series.fosfina_mq135.push({ ts, value: fos });
    }
    if (Number.isFinite(co)) {
        room.values.co_mq7.push(co);
        room.series.co_mq7.push({ ts, value: co });
    }
    if (Number.isFinite(temp) && Number.isFinite(hum)) {
        room.pairs.temp_hum.push([temp, hum]);
    }
    if (Number.isFinite(fos) && Number.isFinite(co)) {
        room.pairs.fosfina_co.push([fos, co]);
    }
}

const dayNames = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];
const analysisRows = [];

function analyzeSeries(seriesArr, bounds, range, extremeBounds) {
    const data = seriesArr.slice().sort((a, b) => a.ts - b.ts);
    let outRange = 0;
    let anomalies = 0;
    const hourCounts = {};
    const dayCounts = {};
    let maxStreak = 0;
    let streak = 0;

    for (const item of data) {
        const v = item.value;
        const isOutRange = range
            ? (v < range.min || v > range.max)
            : (Number.isFinite(extremeBounds.low) && Number.isFinite(extremeBounds.high)
                ? (v < extremeBounds.low || v > extremeBounds.high)
                : false);
        if (isOutRange) outRange += 1;

        const isAnom = bounds.lower !== null && (v < bounds.lower || v > bounds.upper);
        if (isAnom) {
            anomalies += 1;
            addCount(hourCounts, item.ts.getHours());
            addCount(dayCounts, dayNames[item.ts.getDay()]);
            streak += 1;
            if (streak > maxStreak) maxStreak = streak;
        } else {
            streak = 0;
        }
    }

    return { outRange, anomalies, hourCounts, dayCounts, maxStreak };
}

function categoryCountsRange(arr, range) {
    const counts = { baja: 0, normal: 0, alta: 0 };
    for (const v of arr) {
        if (v < range.min) counts.baja += 1;
        else if (v > range.max) counts.alta += 1;
        else counts.normal += 1;
    }
    return counts;
}

function categoryCountsQuartiles(arr, q1, q3) {
    if (!Number.isFinite(q1) || !Number.isFinite(q3)) return null;
    const counts = { baja: 0, media: 0, alta: 0 };
    for (const v of arr) {
        if (v < q1) counts.baja += 1;
        else if (v > q3) counts.alta += 1;
        else counts.media += 1;
    }
    return counts;
}

function meanByPeriod(seriesArr, cutoff, isAfter) {
    const values = seriesArr.filter((p) => isAfter ? p.ts > cutoff : p.ts <= cutoff).map((p) => p.value);
    return mean(values);
}

for (const room of Object.values(rooms)) {
    const values = room.values;
    const series = room.series;

    const tempStats = {
        mean: mean(values.temperatura_c),
        median: median(values.temperatura_c),
        mode: mode(values.temperatura_c),
        min: values.temperatura_c.length ? Math.min(...values.temperatura_c) : null,
        max: values.temperatura_c.length ? Math.max(...values.temperatura_c) : null
    };
    const humStats = {
        mean: mean(values.humedad_pct),
        median: median(values.humedad_pct),
        mode: mode(values.humedad_pct),
        min: values.humedad_pct.length ? Math.min(...values.humedad_pct) : null,
        max: values.humedad_pct.length ? Math.max(...values.humedad_pct) : null
    };
    const fosStats = {
        mean: mean(values.fosfina_mq135),
        median: median(values.fosfina_mq135),
        mode: mode(values.fosfina_mq135),
        min: values.fosfina_mq135.length ? Math.min(...values.fosfina_mq135) : null,
        max: values.fosfina_mq135.length ? Math.max(...values.fosfina_mq135) : null
    };
    const coStats = {
        mean: mean(values.co_mq7),
        median: median(values.co_mq7),
        mode: mode(values.co_mq7),
        min: values.co_mq7.length ? Math.min(...values.co_mq7) : null,
        max: values.co_mq7.length ? Math.max(...values.co_mq7) : null
    };

    const tempVar = variance(values.temperatura_c, tempStats.mean);
    const humVar = variance(values.humedad_pct, humStats.mean);
    const fosVar = variance(values.fosfina_mq135, fosStats.mean);
    const coVar = variance(values.co_mq7, coStats.mean);

    const tempBounds = iqrBounds(values.temperatura_c);
    const humBounds = iqrBounds(values.humedad_pct);
    const fosBounds = iqrBounds(values.fosfina_mq135);
    const coBounds = iqrBounds(values.co_mq7);

    const fosExtreme = percentileBounds(values.fosfina_mq135, 0.1, 0.9);
    const coExtreme = percentileBounds(values.co_mq7, 0.1, 0.9);

    const tempAnalysis = analyzeSeries(series.temperatura_c, tempBounds, tempRange, { low: null, high: null });
    const humAnalysis = analyzeSeries(series.humedad_pct, humBounds, humRange, { low: null, high: null });
    const fosAnalysis = analyzeSeries(series.fosfina_mq135, fosBounds, null, fosExtreme);
    const coAnalysis = analyzeSeries(series.co_mq7, coBounds, null, coExtreme);

    const cutoff = room.maxTs ? new Date(room.maxTs.getTime() - 15 * 24 * 60 * 60 * 1000) : null;
    const comparacion = cutoff ? {
        periodo_a: { inicio: toSqlDate(room.minTs), fin: toSqlDate(cutoff) },
        periodo_b: { inicio: toSqlDate(cutoff), fin: toSqlDate(room.maxTs) },
        deltas: {
            temp_promedio: round(meanByPeriod(series.temperatura_c, cutoff, true) - meanByPeriod(series.temperatura_c, cutoff, false), 2),
            hum_promedio: round(meanByPeriod(series.humedad_pct, cutoff, true) - meanByPeriod(series.humedad_pct, cutoff, false), 2),
            fosfina_promedio: round(meanByPeriod(series.fosfina_mq135, cutoff, true) - meanByPeriod(series.fosfina_mq135, cutoff, false), 2),
            co_promedio: round(meanByPeriod(series.co_mq7, cutoff, true) - meanByPeriod(series.co_mq7, cutoff, false), 2)
        }
    } : null;

    const distribucion = {
        temperatura_c: categoryCountsRange(values.temperatura_c, tempRange),
        humedad_pct: categoryCountsRange(values.humedad_pct, humRange),
        fosfina_mq135: categoryCountsQuartiles(values.fosfina_mq135, fosBounds.q1, fosBounds.q3),
        co_mq7: categoryCountsQuartiles(values.co_mq7, coBounds.q1, coBounds.q3)
    };

    const patrones = {
        temperatura_c: {
            hora_pico_anomalias: peakKey(tempAnalysis.hourCounts),
            dia_pico_anomalias: peakKey(tempAnalysis.dayCounts),
            max_racha_anomalias: tempAnalysis.maxStreak
        },
        humedad_pct: {
            hora_pico_anomalias: peakKey(humAnalysis.hourCounts),
            dia_pico_anomalias: peakKey(humAnalysis.dayCounts),
            max_racha_anomalias: humAnalysis.maxStreak
        },
        fosfina_mq135: {
            hora_pico_anomalias: peakKey(fosAnalysis.hourCounts),
            dia_pico_anomalias: peakKey(fosAnalysis.dayCounts),
            max_racha_anomalias: fosAnalysis.maxStreak
        },
        co_mq7: {
            hora_pico_anomalias: peakKey(coAnalysis.hourCounts),
            dia_pico_anomalias: peakKey(coAnalysis.dayCounts),
            max_racha_anomalias: coAnalysis.maxStreak
        }
    };

    const corrTempHum = pearson(room.pairs.temp_hum);
    const corrFosCo = pearson(room.pairs.fosfina_co);

    const relaciones = {
        corr_temp_hum: round(corrTempHum, 4),
        corr_fosfina_co: round(corrFosCo, 4),
        n_temp_hum: room.pairs.temp_hum.length,
        n_fosfina_co: room.pairs.fosfina_co.length
    };

    const justificacion = {
        temperatura_c: {
            tendencia_central: 'Serie continua; promedio, mediana y moda describen el nivel tipico.',
            dispersion: 'Rango, varianza y desviacion muestran variabilidad termica.',
            frecuencia: 'Conteos fuera del rango 18-25C reflejan confort.',
            temporal: 'Horas y dias pico de anomalias indican patrones operativos.',
            relacion: 'Relacion con humedad apoya diagnostico ambiental.',
            anomalias: 'IQR detecta valores atipicos sin asumir distribucion.'
        },
        humedad_pct: {
            tendencia_central: 'Promedio y mediana resumen humedad habitual.',
            dispersion: 'Rango y desviacion evidencian oscilaciones.',
            frecuencia: 'Fuera de 30-60% identifica condiciones criticas.',
            temporal: 'Picos de anomalias muestran episodios de riesgo.',
            relacion: 'Relacion con temperatura aporta contexto.',
            anomalias: 'IQR identifica lecturas inusuales.'
        },
        fosfina_mq135: {
            tendencia_central: 'Valores crudos requieren resumen robusto.',
            dispersion: 'Varianza y rango reflejan cambios de gas.',
            frecuencia: 'Extremos se estiman con percentiles p10/p90.',
            temporal: 'Picos de anomalias sugieren eventos puntuales.',
            relacion: 'Relacion con CO ayuda a validar episodios.',
            anomalias: 'IQR resalta lecturas fuera de lo comun.'
        },
        co_mq7: {
            tendencia_central: 'Promedio y mediana resumen carga de gas.',
            dispersion: 'Rango y desviacion muestran volatilidad.',
            frecuencia: 'Extremos se basan en percentiles p10/p90.',
            temporal: 'Horas/dias pico permiten detectar patrones.',
            relacion: 'Relacion con fosfina revela eventos compartidos.',
            anomalias: 'IQR identifica picos inesperados.'
        }
    };

    const limitaciones = {
        ventana: 'Analisis limitado a los ultimos 30 dias por habitacion.',
        datos: 'Si hay huecos de muestreo, las estadisticas pueden sesgarse.',
        moda: 'Moda aproximada por redondeo a 2 decimales.',
        gases: 'Fosfina/CO usan percentiles por falta de umbrales crudos.',
        correlaciones: 'Correlaciones nulas si no hay variabilidad suficiente.'
    };

    analysisRows.push({
        id_habitacion: room.id_habitacion,
        periodo_dias: 30,
        total_registros: room.total,
        fecha_inicio_analisis: toSqlDate(room.minTs),
        fecha_fin_analisis: toSqlDate(room.maxTs),
        fecha_generacion: toSqlDate(new Date()),
        temp_promedio: round(tempStats.mean),
        temp_mediana: round(tempStats.median),
        temp_moda: round(tempStats.mode),
        temp_minima: round(tempStats.min),
        temp_maxima: round(tempStats.max),
        temp_rango: round((Number.isFinite(tempStats.max) && Number.isFinite(tempStats.min)) ? tempStats.max - tempStats.min : null),
        temp_stddev: round(stddev(values.temperatura_c, tempStats.mean)),
        temp_varianza: round(tempVar),
        temp_fuera_rango: tempAnalysis.outRange,
        temp_anomalias: tempAnalysis.anomalies,
        hum_promedio: round(humStats.mean),
        hum_mediana: round(humStats.median),
        hum_moda: round(humStats.mode),
        hum_minima: round(humStats.min),
        hum_maxima: round(humStats.max),
        hum_rango: round((Number.isFinite(humStats.max) && Number.isFinite(humStats.min)) ? humStats.max - humStats.min : null),
        hum_stddev: round(stddev(values.humedad_pct, humStats.mean)),
        hum_varianza: round(humVar),
        hum_fuera_rango: humAnalysis.outRange,
        hum_anomalias: humAnalysis.anomalies,
        fosfina_promedio: round(fosStats.mean),
        fosfina_mediana: round(fosStats.median),
        fosfina_moda: round(fosStats.mode),
        fosfina_minima: round(fosStats.min),
        fosfina_maxima: round(fosStats.max),
        fosfina_rango: round((Number.isFinite(fosStats.max) && Number.isFinite(fosStats.min)) ? fosStats.max - fosStats.min : null),
        fosfina_stddev: round(stddev(values.fosfina_mq135, fosStats.mean)),
        fosfina_varianza: round(fosVar),
        fosfina_fuera_rango: fosAnalysis.outRange,
        fosfina_anomalias: fosAnalysis.anomalies,
        co_promedio: round(coStats.mean),
        co_mediana: round(coStats.median),
        co_moda: round(coStats.mode),
        co_minima: round(coStats.min),
        co_maxima: round(coStats.max),
        co_rango: round((Number.isFinite(coStats.max) && Number.isFinite(coStats.min)) ? coStats.max - coStats.min : null),
        co_stddev: round(stddev(values.co_mq7, coStats.mean)),
        co_varianza: round(coVar),
        co_fuera_rango: coAnalysis.outRange,
        co_anomalias: coAnalysis.anomalies,
        corr_temp_hum: round(corrTempHum, 4),
        corr_fosfina_co: round(corrFosCo, 4),
        distribucion_categorias: distribucion,
        patrones_temporales: patrones,
        relaciones_variables: relaciones,
        comparacion_periodos: comparacion,
        justificacion_analisis: justificacion,
        limitaciones
    });
}

msg.payload = analysisRows;
return msg;
